\begin{tikzpicture}[line cap=round,line join=round,>=stealth,scale=0.95]
% left panel: concave mirror close to object for enlarged viewing
\draw[thick] (0,1.3) .. controls (0.95,0.35) and (0.95,-0.35) .. (0,-1.3);
\foreach \y in {-1.1,-0.7,-0.3,0.1,0.5,0.9} {\draw[thin] (-0.02,\y)--++(-0.22,0);}
\node[font=\small] at (0.15,1.65) {concave};
\draw[thick,fill=gray!25] (1.25,-0.22) rectangle (1.55,0.22);
\node[font=\footnotesize] at (1.4,-0.5) {object};
\draw[dashed,thick] (0.5,-0.5) rectangle (0.95,0.5);
\node[font=\footnotesize] at (0.72,0.72) {enlarged};
\node[font=\footnotesize\bfseries] at (0.7,-1.7) {enlarged viewing};
% right panel: concave mirror concentrates parallel rays
\begin{scope}[shift={(4.2,0)}]
\draw[thick] (0,1.3) .. controls (0.95,0.35) and (0.95,-0.35) .. (0,-1.3);
\foreach \y in {-1.1,-0.7,-0.3,0.1,0.5,0.9} {\draw[thin] (-0.02,\y)--++(-0.22,0);}
\draw[->,thick] (2.4,0.7)--(0.55,0.35);
\draw[->,thick] (2.4,0)--(0.35,0);
\draw[->,thick] (2.4,-0.7)--(0.55,-0.35);
\fill (0.95,0) circle (1.5pt);
\node[font=\footnotesize] at (1.15,-0.35) {focus};
\node[font=\footnotesize\bfseries] at (1.2,-1.7) {light concentration};
\end{scope}
\end{tikzpicture}
